package com.xdownload.mobile;import org.junit.Test;import static org.junit.Assert.*;public class DownloadErrorsTest{@Test public void actionableAndNoSecretLeak(){assertEquals("rate",DownloadErrors.classify(new Exception("HTTP 429")));assertEquals("storage",DownloadErrors.classify(new Exception("No space left")));assertEquals("runtime",DownloadErrors.classify(new Exception("JavaScript challenge")));assertEquals("protected",DownloadErrors.classify(new Exception("DRM protected media")));assertEquals("access",DownloadErrors.classify(new Exception("HTTP 403 https://example.org/?token=secret")));assertFalse(DownloadErrors.message(new Exception("HTTP 403 https://example.org/?token=secret"),true).contains("secret"));}}